import Renderer from './lib/Viz/2DRenderer.js'
import SwordTip from './lib/Scene/SwordTip.js'
import Lines from './lib/Scene/Lines.js'
import SwordHilt from './lib/Scene/SwordHilt.js'
import SwordHandle from './lib/Scene/SwordHandle.js'
import BackgroundRays from './lib/Scene/BackgroundRays.js'

async function init() {
   // Create a canvas tag
   const canvasTag = document.createElement('canvas');
   canvasTag.id = "renderCanvas";
   document.body.appendChild(canvasTag);
   // Create a simple renderer
   const renderer = new Renderer(canvasTag);
   await renderer.init();
    await renderer.appendSceneObject(new BackgroundRays(renderer._device, renderer._canvasFormat));
   await renderer.appendSceneObject(new SwordTip(renderer._device, renderer._canvasFormat));

   await renderer.appendSceneObject(new Lines(renderer._device, renderer._canvasFormat));
    await renderer.appendSceneObject(new SwordHilt(renderer._device, renderer._canvasFormat));
    await renderer.appendSceneObject(new SwordHandle(renderer._device, renderer._canvasFormat));

   renderer.render();
   return renderer;
}

init().then( ret => {
   console.log(ret);
 }).catch( error => {
   const pTag = document.createElement('p');
   pTag.innerHTML = navigator.userAgent + "</br>" + error.message;
   document.body.appendChild(pTag);
   document.getElementById("renderCanvas").remove();
});